#include <unity.h>
#include <meter_selection.h>
using namespace meter_ui;
void setUp(){}void tearDown(){}
static void dropdown_choices_fit_and_hidden_rows_cannot_be_selected(){for(Rect area: {Rect{10,10,460,300},Rect{8,8,304,156},Rect{80,80,306,306}}){auto r=selectionLayout(area,35);TEST_ASSERT_TRUE(r.valid);TEST_ASSERT_GREATER_OR_EQUAL(44,r.rowHeight);TEST_ASSERT_TRUE(r.box.x>=area.x&&r.box.y>=area.y&&r.box.x+r.box.w<=area.x+area.w&&r.box.y+r.box.h<=area.y+area.h);SelectionState s;TEST_ASSERT_TRUE(s.begin(35,3,r.visible));TEST_ASSERT_EQUAL(3,s.current());TEST_ASSERT_TRUE(unsigned(s.current())>=s.first()&&unsigned(s.current())<s.first()+r.visible);auto first=r.row(0);TEST_ASSERT_EQUAL(0,r.indexAt(first.x+5,first.y+5));TEST_ASSERT_EQUAL(-1,r.indexAt(first.x+5,r.list.y+r.list.h));s.scrollBy(1000000);TEST_ASSERT_EQUAL(35-r.visible,s.first());int chosen=-1;TEST_ASSERT_TRUE(s.chooseVisible(r.visible-1,chosen));TEST_ASSERT_EQUAL(34,chosen);TEST_ASSERT_FALSE(s.isOpen());}}
static void dropdown_cancel_preserves_current_and_scrolling_is_bounded(){SelectionState s;TEST_ASSERT_FALSE(s.begin(0,0,3));TEST_ASSERT_TRUE(s.begin(4,2,3));s.scrollBy(-9999);TEST_ASSERT_EQUAL(0,s.first());s.cancel();TEST_ASSERT_EQUAL(2,s.current());int chosen=-1;TEST_ASSERT_FALSE(s.chooseVisible(1,chosen));TEST_ASSERT_EQUAL(-1,chosen);TEST_ASSERT_TRUE(s.begin(4,2,4));TEST_ASSERT_FALSE(s.chooseVisible(4,chosen));TEST_ASSERT_TRUE(s.isOpen());}
static void visual_choices_fit_and_hit_the_matching_picture(){auto r=visualSelectionLayout({8,8,464,304},6);TEST_ASSERT_TRUE(r.valid);TEST_ASSERT_EQUAL(2,r.columns);TEST_ASSERT_EQUAL(6,r.visible);TEST_ASSERT_FALSE(r.scrollable);SelectionState state;TEST_ASSERT_TRUE(state.begin(6,5,r.visible,r.rowHeight,r.columns));TEST_ASSERT_EQUAL(0,state.first());for(unsigned i=0;i<6;++i){auto cell=r.row(i);TEST_ASSERT_EQUAL(i,r.indexAt(cell.x+cell.w/2,cell.y+cell.h/2));TEST_ASSERT_TRUE(cell.y+cell.h<=r.box.y+r.box.h);}auto cell=r.row(0);TEST_ASSERT_EQUAL(-1,r.indexAt(cell.x+cell.w+1,cell.y+5));int selected=-1;TEST_ASSERT_TRUE(state.chooseVisible(5,selected));TEST_ASSERT_EQUAL(5,selected);auto small=visualSelectionLayout({8,8,304,156},6);TEST_ASSERT_TRUE(small.valid);TEST_ASSERT_TRUE(small.scrollable);TEST_ASSERT_TRUE(state.begin(6,5,small.visible,small.rowHeight,small.columns));TEST_ASSERT_TRUE(state.first()<=5&&state.first()+small.visible>5);state.scrollBy(1000000);TEST_ASSERT_TRUE(state.chooseVisible(small.visible-1,selected));TEST_ASSERT_EQUAL(5,selected);}
int main(){UNITY_BEGIN();RUN_TEST(dropdown_choices_fit_and_hidden_rows_cannot_be_selected);RUN_TEST(dropdown_cancel_preserves_current_and_scrolling_is_bounded);RUN_TEST(visual_choices_fit_and_hit_the_matching_picture);return UNITY_END();}
